import random

n = 23
fixed_positions = {5: -1, 10: -1, 13: 1, 19: 1}
fixed_c = {12: 0, 13: -3, 16: 0, 19: -1}
free_positions = [i for i in range(n) if i not in fixed_positions]

best_sum_sq = float('inf')
best_seq = None

for trial in range(100000):
    seq = [0] * n
    for i, v in fixed_positions.items():
        seq[i] = v
    for pos in free_positions:
        seq[pos] = random.choice([-1, 1])

    # Compute autocorrelations
    c = {}
    for k in range(1, n):
        val = 0
        for i in range(n - k):
            val += seq[i] * seq[i + k]
        c[k] = val

    # Check fixed autocorrelation constraints
    ok = True
    for k, v in fixed_c.items():
        if c[k] != v:
            ok = False
            break

    if not ok:
        continue

    sum_sq = sum(c[k]**2 for k in range(1, n))
    if sum_sq < best_sum_sq:
        best_sum_sq = sum_sq
        best_seq = seq[:]
        print(f"Trial {trial}: sum_sq = {sum_sq}")
        if sum_sq <= 59:
            print(f"FOUND! seq = {seq}")
            break

print(f"Best found: sum_sq = {best_sum_sq}")
if best_seq:
    print(f"Best seq = {best_seq}")
